window.CIVIL_SET_DATA["past-15"] = {"title":"Past Paper Set 15","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-15-001","src":"PAST-15-001","text":"After storage, the strength of cement","options":[{"key":"a","text":"decreases"},{"key":"b","text":"increases"},{"key":"c","text":"remains same"},{"key":"d","text":"may increase or decrease"}],"answer":"a","explanation":"Stored cement absorbs moisture and CO<sub>2</sub> from the air and partly hydrates (air-sets), so it loses strength: roughly 20% after 3 months and 30–40% after a year.","marks":1,"source":{"kind":"past","set":15,"question":1,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q1 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-15-002","src":"PAST-15-002","text":"What kind of slope do closely spaced equal contour lines indicate?","options":[{"key":"a","text":"Gentle slope"},{"key":"b","text":"Steep slope"},{"key":"c","text":"Flat slope"},{"key":"d","text":"V-sloped"}],"answer":"b","explanation":"Closely spaced contours mean a large change in height over a short horizontal distance, i.e. a steep slope. Equal spacing means a uniform slope.","marks":1,"source":{"kind":"past","set":15,"question":2,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q2 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-15-005","src":"PAST-15-005","text":"The expected out-turn of cement concrete 1:2:4 per mason per day will be","options":[{"key":"a","text":"5.0 m<sup>3</sup>"},{"key":"b","text":"3.5 m<sup>3</sup>"},{"key":"c","text":"2.5 m<sup>3</sup>"},{"key":"d","text":"1.5 m<sup>3</sup>"}],"answer":"a","explanation":"Standard task-work tables give about 5.0 m<sup>3</sup> of 1:2:4 cement concrete per mason per day, with the supporting labourers.","marks":1,"source":{"kind":"past","set":15,"question":5,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q5 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-15-061","src":"PAST-15-061","text":"The area moment of a semi-circular section having diameter \\(d\\) about its diametric axis is","options":[{"key":"a","text":"\\(\\dfrac{\\pi d^2}{36}\\)"},{"key":"b","text":"\\(\\dfrac{\\pi d^2}{128}\\)"},{"key":"c","text":"\\(\\dfrac{\\pi d^4}{64}\\)"},{"key":"d","text":"\\(\\dfrac{\\pi d^4}{128}\\)"}],"answer":"d","explanation":"About its diameter, a semicircle has half the full circle's \\(\\dfrac{\\pi d^4}{64}\\): \\[I = \\dfrac{\\pi d^4}{128}\\]","marks":2,"source":{"kind":"past","set":15,"question":61,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q61 · 2 marks"},"topic":"ACiE0104"},{"id":"PAST-15-069","src":"PAST-15-069","text":"What is the value of the refractive index of diamond?","options":[{"key":"a","text":"1.62"},{"key":"b","text":"1.77"},{"key":"c","text":"2.62"},{"key":"d","text":"2.42"}],"answer":"d","explanation":"Diamond's very high refractive index (about 2.42) gives its brilliance through total internal reflection.","marks":2,"source":{"kind":"past","set":15,"question":69,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q69 · 2 marks"},"topic":"ACiE0101"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-15-007","src":"PAST-15-007","text":"The coefficient of passive earth pressure is","options":[{"key":"a","text":"\\(K_p = \\dfrac{1 + \\sin\\phi}{1 - \\sin\\phi}\\)"},{"key":"b","text":"\\(K_p = \\dfrac{1 - \\sin\\phi}{1 + \\sin\\phi}\\)"},{"key":"c","text":"\\(K_p = (1 - \\sin\\phi)\\)"},{"key":"d","text":"\\(K_p = \\dfrac{1 + \\sin^2\\phi}{1 - \\sin^2\\phi}\\)"}],"answer":"a","explanation":"Rankine's passive coefficient is \\[\\begin{aligned} K_p &amp;= \\dfrac{1 + \\sin\\phi}{1 - \\sin\\phi} \\\\ &amp;= \\tan^2\\left(45^\\circ + \\dfrac{\\phi}{2}\\right) \\end{aligned}\\] Option (b) is \\(K_a\\) and (c) is Jaky's \\(K_0\\).","marks":1,"source":{"kind":"past","set":15,"question":7,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q7 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-15-010","src":"PAST-15-010","text":"As per the IS code, what is the maximum permissible settlement for an isolated foundation on sand?","options":[{"key":"a","text":"40 mm"},{"key":"b","text":"10 mm"},{"key":"c","text":"20 mm"},{"key":"d","text":"60 mm"}],"answer":"a","explanation":"IS 1904 permits about 40 mm total settlement for isolated footings on sand (and hard clay) and about 65 mm on plastic clay.","marks":1,"source":{"kind":"past","set":15,"question":10,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q10 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-15-012","src":"PAST-15-012","text":"Which of the following is a correct formula for dry density?","options":[{"key":"a","text":"\\(\\dfrac{G\\gamma_w}{1 + e}\\)"},{"key":"b","text":"\\(\\dfrac{\\gamma_b}{1 + w}\\)"},{"key":"c","text":"\\(\\dfrac{(1 - n_a)G\\gamma_w}{1 + wG}\\)"},{"key":"d","text":"All"}],"answer":"d","explanation":"All three are equivalent expressions for the dry unit weight: \\[\\gamma_d = \\dfrac{G\\gamma_w}{1 + e} = \\dfrac{\\gamma}{1 + w}\\] \\[\\gamma_d = \\dfrac{(1 - n_a)G\\gamma_w}{1 + wG}\\]","marks":1,"source":{"kind":"past","set":15,"question":12,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q12 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-15-014","src":"PAST-15-014","text":"Which of the following doesn't contribute to the stability of a slope?","options":[{"key":"a","text":"Surface drainage"},{"key":"b","text":"Sub surface drainage"},{"key":"c","text":"Retaining wall"},{"key":"d","text":"Increased slope angle"}],"answer":"d","explanation":"Drainage lowers pore pressure and retaining walls support the toe, both improving stability. Steepening the slope increases the driving force and reduces the factor of safety.","marks":1,"source":{"kind":"past","set":15,"question":14,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q14 · 1 mark"},"topic":"ACiE0203"},{"id":"PAST-15-015","src":"PAST-15-015","text":"The coefficient of curvature for a well graded soil lies between","options":[{"key":"a","text":"1 to 3"},{"key":"b","text":"1 to 2"},{"key":"c","text":"3 to 5"},{"key":"d","text":"5 to 7"}],"answer":"a","explanation":"A well-graded soil has \\[C_c = \\dfrac{D_{30}^2}{D_{10}D_{60}}\\] between 1 and 3, together with \\(C_u \\gt 4\\) (gravel) or \\(C_u \\gt 6\\) (sand).","marks":1,"source":{"kind":"past","set":15,"question":15,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q15 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-15-032","src":"PAST-15-032","text":"When an individual footing accommodates two or more than two columns, it is a","options":[{"key":"a","text":"combined footing"},{"key":"b","text":"isolated footing"},{"key":"c","text":"strap footing"},{"key":"d","text":"pile foundation"}],"answer":"a","explanation":"A footing common to two or more columns is a combined footing. A strap footing links two separate footings by a beam.","marks":1,"source":{"kind":"past","set":15,"question":32,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q32 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-15-047","src":"PAST-15-047","text":"In dense soil, the shear failure that occurs is","options":[{"key":"a","text":"general shear failure"},{"key":"b","text":"local shear failure"},{"key":"c","text":"punching shear failure"},{"key":"d","text":"deep shear failure"}],"answer":"a","explanation":"Dense sands and stiff clays fail in general shear, with well-defined slip surfaces reaching the ground and heaving. Loose soils show local or punching shear.","marks":1,"source":{"kind":"past","set":15,"question":47,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q47 · 1 mark"},"topic":"ACiE0206"},{"id":"PAST-15-062","src":"PAST-15-062","text":"If the specific gravity of soil is 1.527, then find its specific weight.","options":[{"key":"a","text":"15270 N/m<sup>3</sup>"},{"key":"b","text":"1527 N/cm<sup>3</sup>"},{"key":"c","text":"14980 N/m<sup>3</sup>"},{"key":"d","text":"1498 N/cm<sup>3</sup>"}],"answer":"c","explanation":"The specific weight is \\[\\begin{aligned} \\gamma &amp;= G\\gamma_w = 1.527 \\times 9810 \\\\ &amp;\\approx 14{,}980 \\end{aligned}\\] N per m<sup>3</sup>.","marks":2,"source":{"kind":"past","set":15,"question":62,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q62 · 2 marks"},"topic":"ACiE0201"},{"id":"PAST-15-063","src":"PAST-15-063","text":"The bearing capacity of a circular footing is calculated as","options":[{"key":"a","text":"\\(Q_u = cN_c\\) \\(+\\,qN_q\\) \\(+\\,0.5\\gamma BN_\\gamma\\)"},{"key":"b","text":"\\(Q_u = 1.3cN_c\\) \\(+\\,qN_q\\) \\(+\\,0.5\\gamma BN_\\gamma\\)"},{"key":"c","text":"\\(Q_u = 1.3cN_c\\) \\(+\\,qN_q\\) \\(+\\,0.4\\gamma BN_\\gamma\\)"},{"key":"d","text":"\\(Q_u = 1.3cN_c\\) \\(+\\,qN_q\\) \\(+\\,0.3\\gamma BN_\\gamma\\)"}],"answer":"d","explanation":"Terzaghi's circular footing, with \\(B\\) the diameter, gives \\[\\begin{aligned} q_u &amp;= 1.3cN_c + qN_q \\\\ &amp;\\quad + 0.3\\gamma BN_\\gamma \\end{aligned}\\] A square footing uses \\(0.4\\gamma BN_\\gamma\\).","marks":2,"source":{"kind":"past","set":15,"question":63,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q63 · 2 marks"},"topic":"ACiE0206"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-15-016","src":"PAST-15-016","text":"The difference between the total energy line and the hydraulic grade line represents the","options":[{"key":"a","text":"piezometric head"},{"key":"b","text":"pressure head"},{"key":"c","text":"elevation head"},{"key":"d","text":"velocity head"}],"answer":"d","explanation":"The TEL lies above the HGL by the velocity head \\(\\dfrac{V^2}{2g}\\).","marks":1,"source":{"kind":"past","set":15,"question":16,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q16 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-15-017","src":"PAST-15-017","text":"The rise of a liquid in a capillary tube is due to","options":[{"key":"a","text":"viscosity"},{"key":"b","text":"osmosis"},{"key":"c","text":"diffusion"},{"key":"d","text":"surface tension"}],"answer":"d","explanation":"Capillary rise results from surface tension together with adhesion between the liquid and the tube wall: \\[h = \\dfrac{4\\sigma\\cos\\theta}{\\rho gd}\\]","marks":1,"source":{"kind":"past","set":15,"question":17,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q17 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-15-018","src":"PAST-15-018","text":"For liquid fluids, capillary rise (or fall) will …… with a rise in temperature.","options":[{"key":"a","text":"increase"},{"key":"b","text":"decrease"},{"key":"c","text":"remain constant"},{"key":"d","text":"first decrease then increase"}],"answer":"b","explanation":"Surface tension falls as temperature rises, so the capillary rise (or depression) decreases.","marks":1,"source":{"kind":"past","set":15,"question":18,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q18 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-15-019","src":"PAST-15-019","text":"Super critical flow occurs in a","options":[{"key":"a","text":"channel with a mild slope"},{"key":"b","text":"channel with a steep slope"},{"key":"c","text":"horizontal channel"},{"key":"d","text":"all the above"}],"answer":"b","explanation":"On a steep slope the normal depth is below the critical depth, so uniform flow is supercritical (Fr &gt; 1). Mild slopes give subcritical flow.","marks":1,"source":{"kind":"past","set":15,"question":19,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q19 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-15-020","src":"PAST-15-020","text":"The head loss at the entrance of the pipe is …… that at its exit.","options":[{"key":"a","text":"equal to"},{"key":"b","text":"half"},{"key":"c","text":"twice"},{"key":"d","text":"four times"}],"answer":"b","explanation":"The entrance loss \\(0.5\\dfrac{V^2}{2g}\\) is half the exit loss \\(\\dfrac{V^2}{2g}\\).","marks":1,"source":{"kind":"past","set":15,"question":20,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q20 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-15-021","src":"PAST-15-021","text":"The friction factor for laminar flow is given by","options":[{"key":"a","text":"64/Re"},{"key":"b","text":"16/Re"},{"key":"c","text":"Re/16"},{"key":"d","text":"Re/64"}],"answer":"a","explanation":"For laminar pipe flow, the Darcy friction factor is \\[f = \\dfrac{64}{Re}\\] The Fanning coefficient is \\(\\dfrac{16}{Re}\\).","marks":1,"source":{"kind":"past","set":15,"question":21,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q21 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-15-022","src":"PAST-15-022","text":"What do you mean by cold frontal precipitation?","options":[{"key":"a","text":"Small catchment area with heavy precipitation"},{"key":"b","text":"Small catchment area with moderate precipitation"},{"key":"c","text":"Large catchment area with heavy precipitation"},{"key":"d","text":"Large catchment area with moderate precipitation"}],"answer":"a","explanation":"A cold front lifts warm air steeply, giving intense (heavy) rain of short duration over a relatively narrow area. A warm front gives moderate rain over a wide area.","marks":1,"source":{"kind":"past","set":15,"question":22,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q22 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-15-023","src":"PAST-15-023","text":"A Bourdon gauge is used to measure","options":[{"key":"a","text":"absolute pressure"},{"key":"b","text":"gauge pressure"},{"key":"c","text":"local atmospheric pressure"},{"key":"d","text":"standard atmospheric pressure"}],"answer":"b","explanation":"A Bourdon tube deflects according to the difference between the fluid pressure and the surrounding atmosphere, so it reads gauge pressure.","marks":1,"source":{"kind":"past","set":15,"question":23,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q23 · 1 mark"},"topic":"ACiE0302"},{"id":"PAST-15-024","src":"PAST-15-024","text":"The discharge-stage relationship is known as","options":[{"key":"a","text":"hydrograph"},{"key":"b","text":"rating curve"},{"key":"c","text":"flow duration curve"},{"key":"d","text":"unit hydrograph"}],"answer":"b","explanation":"A rating curve relates the stage (water level) at a gauging site to the discharge, so continuous stage records can be converted into flows.","marks":1,"source":{"kind":"past","set":15,"question":24,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q24 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-15-064","src":"PAST-15-064","text":"Find the value of the hydraulic radius in the most economical triangular channel.","options":[{"key":"a","text":"\\(\\dfrac{y}{\\sqrt{2}}\\)"},{"key":"b","text":"\\(\\dfrac{y}{2\\sqrt{2}}\\)"},{"key":"c","text":"\\(\\dfrac{y}{2}\\)"},{"key":"d","text":"\\(2\\sqrt{2}\\,y\\)"}],"answer":"b","explanation":"The best triangular section has \\(45^\\circ\\) side slopes: \\(A = y^2\\) and \\(P = 2\\sqrt{2}\\,y\\), so \\[R = \\dfrac{A}{P} = \\dfrac{y}{2\\sqrt{2}}\\]","marks":2,"source":{"kind":"past","set":15,"question":64,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q64 · 2 marks"},"topic":"ACiE0305"},{"id":"PAST-15-065","src":"PAST-15-065","text":"If the particle size is 6 cm, find Manning's rugosity coefficient.","options":[{"key":"a","text":"0.016"},{"key":"b","text":"0.028"},{"key":"c","text":"0.026"},{"key":"d","text":"0.038"}],"answer":"c","explanation":"By Strickler's relation, with \\(d\\) in m, \\[n \\approx \\dfrac{d^{1{/}6}}{24} = \\dfrac{0.06^{1{/}6}}{24}\\] \\[= \\dfrac{0.626}{24} \\approx 0.026\\]","marks":2,"source":{"kind":"past","set":15,"question":65,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q65 · 2 marks"},"topic":"ACiE0305"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-15-025","src":"PAST-15-025","text":"At the point of contra flexure, the bending moment","options":[{"key":"a","text":"is equal to zero"},{"key":"b","text":"changes sign"},{"key":"c","text":"is maximum"},{"key":"d","text":"is minimum"}],"answer":"b","explanation":"A point of contraflexure is where the bending moment changes sign (hogging to sagging). The moment passes through zero there, and the key selects the sign change as its defining feature.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-15-025-point-of-contraflexure.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Point of contraflexure on an overhanging beam'><img src='assets/civil-past-solutions/past-15-025-point-of-contraflexure.svg' width='720' height='420' loading='lazy' decoding='async' alt='With a uniform load over a span and an overhang, the moment is sagging near A and hogging over B. It changes sign, passing through zero, at the point of contraflexure, here 0.75L from A.'></a><figcaption>Point of contraflexure on an overhanging beam</figcaption></figure>","marks":1,"source":{"kind":"past","set":15,"question":25,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q25 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-15-027","src":"PAST-15-027","text":"In influence line diagrams (ILD)","options":[{"key":"a","text":"points remain fixed, position of load changes"},{"key":"b","text":"points change, position of loads remains fixed"},{"key":"c","text":"both of them change"},{"key":"d","text":"neither of them changes"}],"answer":"a","explanation":"An influence line plots a response at one fixed point as a unit load moves across the structure.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-05-053-what-an-influence-line-shows.svg' target='_blank' rel='noopener noreferrer' aria-label='Open An influence line: the section stays fixed while the load moves'><img src='assets/civil-past-solutions/past-05-053-what-an-influence-line-shows.svg' width='720' height='420' loading='lazy' decoding='async' alt='An influence line gives one response, here the moment at a fixed section C, as a unit load moves across the span. Each ordinate is the value at C when the unit load stands directly above that point.'></a><figcaption>An influence line: the section stays fixed while the load moves</figcaption></figure>","marks":1,"source":{"kind":"past","set":15,"question":27,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q27 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-15-028","src":"PAST-15-028","text":"Euler's buckling load for a column with both ends fixed is","options":[{"key":"a","text":"\\(\\dfrac{\\pi^2EI}{L^2}\\)"},{"key":"b","text":"\\(\\dfrac{2\\pi^2EI}{L^2}\\)"},{"key":"c","text":"\\(\\dfrac{4\\pi^2EI}{L^2}\\)"},{"key":"d","text":"\\(\\dfrac{\\pi^2EI}{4L^2}\\)"}],"answer":"c","explanation":"With \\(l_e = \\dfrac{L}{2}\\), \\[P = \\dfrac{\\pi^2EI}{(L{/}2)^2} = \\dfrac{4\\pi^2EI}{L^2}\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-15-028-euler-loads-for-four-end-conditions.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Euler loads for the four end conditions'><img src='assets/civil-past-solutions/past-15-028-euler-loads-for-four-end-conditions.svg' width='720' height='420' loading='lazy' decoding='async' alt='With P = π squared EI/le squared, the crippling load in units of π squared EI/L squared is 1/4 for fixed-free, 1 for hinged-hinged, about 2 for fixed-hinged and 4 for fixed-fixed, where le = L/2.'></a><figcaption>Euler loads for the four end conditions</figcaption></figure>","marks":1,"source":{"kind":"past","set":15,"question":28,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q28 · 1 mark"},"topic":"ACiE0403"},{"id":"PAST-15-029","src":"PAST-15-029","text":"The major (normal) stress produced on the diagonal plane is expressed as","options":[{"key":"a","text":"\\(\\dfrac{f_x + f_y}{2}\\)"},{"key":"b","text":"\\(\\dfrac{f_x + f_y}{2} + \\tau_{xy}\\)"},{"key":"c","text":"\\(\\dfrac{f_x + f_y}{2}\\) \\(+\\dfrac{\\sqrt{(f_x - f_y)^2 + 4\\tau_{xy}^2}}{2}\\)"},{"key":"d","text":"\\(\\dfrac{f_x - f_y}{2}\\)"}],"answer":"b","explanation":"On the \\(45^\\circ\\) (diagonal) plane, \\(\\cos 2\\theta = 0\\) and \\(\\sin 2\\theta = 1\\), so \\[\\sigma = \\dfrac{f_x + f_y}{2} + \\tau_{xy}\\] which is the key's answer. The general major principal stress is expression (c).<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-15-029-normal-stress-on-the-diagonal-plane.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Normal stress on the diagonal plane of an element'><img src='assets/civil-past-solutions/past-15-029-normal-stress-on-the-diagonal-plane.svg' width='720' height='420' loading='lazy' decoding='async' alt='On a plane at θ the normal stress is (fx + fy)/2 + ((fx - fy)/2) cos 2θ + τxy sin 2θ. On the 45 degree diagonal plane cos 2θ = 0 and sin 2θ = 1, leaving (fx + fy)/2 + τxy.'></a><figcaption>Normal stress on the diagonal plane of an element</figcaption></figure>","marks":1,"source":{"kind":"past","set":15,"question":29,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q29 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-15-030","src":"PAST-15-030","text":"The stiffness factor when the far end is a vertical guided roller is","options":[{"key":"a","text":"\\(0\\)"},{"key":"b","text":"\\(\\dfrac{EI}{L}\\)"},{"key":"c","text":"\\(\\dfrac{3EI}{L}\\)"},{"key":"d","text":"\\(\\dfrac{4EI}{L}\\)"}],"answer":"b","explanation":"With the far end free to slide but not rotate (guided), a unit rotation at the near end needs a moment of EI/L. It is 4EI/L for a fixed far end and 3EI/L for a pinned one.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-15-030-stiffness-far-end-guided.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Moment needed to rotate the near end with a guided far end'><img src='assets/civil-past-solutions/past-15-030-stiffness-far-end-guided.svg' width='720' height='420' loading='lazy' decoding='async' alt='When the far end B can slide sideways but cannot rotate, the member carries no shear, so its moment is constant along the length. A unit rotation at A then needs only EI/L, compared with 4EI/L for a fixed far end.'></a><figcaption>Moment needed to rotate the near end with a guided far end</figcaption></figure>","marks":1,"source":{"kind":"past","set":15,"question":30,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q30 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-15-031","src":"PAST-15-031","text":"The property by which elongation of a material occurs due to a tensile load is","options":[{"key":"a","text":"hardness"},{"key":"b","text":"ductility"},{"key":"c","text":"brittleness"},{"key":"d","text":"malleability"}],"answer":"b","explanation":"Ductility is the ability to undergo large plastic elongation in tension before fracture. Malleability is the corresponding ability under compression (hammering, rolling).","marks":1,"source":{"kind":"past","set":15,"question":31,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q31 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-15-066","src":"PAST-15-066","text":"A beam has a fixed end at A and a roller at the other end B. If a load of 10 kN is applied at an internal hinge at a distance l/3 from the fixed end, find the reaction at end B.","options":[{"key":"a","text":"0 kN"},{"key":"b","text":"2.5 kN"},{"key":"c","text":"7.5 kN"},{"key":"d","text":"10 kN"}],"answer":"a","explanation":"The load acts exactly at the hinge. The portion from the hinge to B carries no load and cannot transfer moment, so its end reactions are zero. The whole 10 kN goes to the fixed end through the cantilever part AH.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-15-066-load-at-an-internal-hinge.svg' target='_blank' rel='noopener noreferrer' aria-label='Open A load applied exactly at the internal hinge'><img src='assets/civil-past-solutions/past-15-066-load-at-an-internal-hinge.svg' width='720' height='420' loading='lazy' decoding='async' alt='The load of 10 kN sits on the hinge at l/3. The part from the hinge to B carries no load and the hinge passes no moment, so that part is unloaded and RB = 0. The part AH works as a cantilever and the fixed end takes the whole 10 kN.'></a><figcaption>A load applied exactly at the internal hinge</figcaption></figure>","marks":2,"source":{"kind":"past","set":15,"question":66,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q66 · 2 marks"},"topic":"ACiE0404"},{"id":"PAST-15-067","src":"PAST-15-067","text":"A UVL varying from zero at one end to \\(w\\) at the other is applied on a two hinged parabolic arch. The formula to calculate the horizontal thrust is","options":[{"key":"a","text":"\\(\\dfrac{wl^2}{8H}\\)"},{"key":"b","text":"\\(\\dfrac{wl^2}{12H}\\)"},{"key":"c","text":"\\(\\dfrac{wl^2}{16H}\\)"},{"key":"d","text":"\\(\\dfrac{wl^2}{4H}\\)"}],"answer":"c","explanation":"The triangular load equals a UDL of \\(\\dfrac{w}{2}\\) plus an antisymmetric part, which produces no thrust. So, with rise \\(h\\), \\[H = \\dfrac{(w{/}2)l^2}{8h} = \\dfrac{wl^2}{16h}\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-15-067-triangular-load-on-a-two-hinged-arch.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Triangular load on a two-hinged parabolic arch'><img src='assets/civil-past-solutions/past-15-067-triangular-load-on-a-two-hinged-arch.svg' width='720' height='420' loading='lazy' decoding='async' alt='A load rising from zero to w is a uniform load of w/2 plus an antisymmetric load of -w/2 to +w/2. The antisymmetric part gives no thrust, so H is that of the uniform w/2: (w/2)l squared/8h = wl squared/16h, with h the rise.'></a><figcaption>Triangular load on a two-hinged parabolic arch</figcaption></figure>","marks":2,"source":{"kind":"past","set":15,"question":67,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q67 · 2 marks"},"topic":"ACiE0406"}]},{"name":"Design of Structures","questions":[{"id":"PAST-15-004","src":"PAST-15-004","text":"Which one of the following is incorrect regarding plasticizers?","options":[{"key":"a","text":"Used for flowing mortar in heavy dams"},{"key":"b","text":"Increase strength with reduction in water and increasing cement"},{"key":"c","text":"Act as both water reducers and retarders"},{"key":"d","text":"Enhance workability without affecting strength"}],"answer":"a","explanation":"Plasticisers (water reducers) improve workability, or allow less water for the same workability and so higher strength, and often retard set. Per the key, statement (a) about flowing mortar for heavy dams is the incorrect one.","marks":1,"source":{"kind":"past","set":15,"question":4,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q4 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-15-006","src":"PAST-15-006","text":"The type of stone used for the construction of a retaining wall is","options":[{"key":"a","text":"soft"},{"key":"b","text":"hard"},{"key":"c","text":"light"},{"key":"d","text":"heavy"}],"answer":"d","explanation":"A retaining wall resists earth pressure largely by its own weight, so heavy (dense, strong) stone is preferred for gravity masonry walls.","marks":1,"source":{"kind":"past","set":15,"question":6,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q6 · 1 mark"},"topic":"ACiE0506"},{"id":"PAST-15-008","src":"PAST-15-008","text":"Sands of zone I are","options":[{"key":"a","text":"coarse sand"},{"key":"b","text":"medium sand"},{"key":"c","text":"medium to fine sand"},{"key":"d","text":"fine sand"}],"answer":"a","explanation":"IS 383 grading zones run from Zone I (coarsest) to Zone IV (finest).","marks":1,"source":{"kind":"past","set":15,"question":8,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q8 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-15-026","src":"PAST-15-026","text":"The shape factor of a cross section with diamond shape under flexure is","options":[{"key":"a","text":"1"},{"key":"b","text":"2"},{"key":"c","text":"3"},{"key":"d","text":"4"}],"answer":"b","explanation":"For a diamond (a square with a diagonal vertical), \\[\\dfrac{Z_p}{Z_e} = 2\\] It is 1.5 for a rectangle and 1.7 for a circle.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-15-026-shape-factor-of-a-diamond.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Shape factor of a diamond section'><img src='assets/civil-past-solutions/past-15-026-shape-factor-of-a-diamond.svg' width='720' height='420' loading='lazy' decoding='async' alt='For a diamond of width b and depth d, I = bd cubed/48 so Ze = bd squared/24. When fully plastic each half, of area bd/4, acts at d/6 from the neutral axis, so Zp = 2(bd/4)(d/6) = bd squared/12 and the shape factor is 2.'></a><figcaption>Shape factor of a diamond section</figcaption></figure>","marks":1,"source":{"kind":"past","set":15,"question":26,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q26 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-15-033","src":"PAST-15-033","text":"A super plasticizer is used in concrete to","options":[{"key":"a","text":"increase workability"},{"key":"b","text":"reduce quantity of cement"},{"key":"c","text":"reduce quantity of mixing water"},{"key":"d","text":"all of these"}],"answer":"d","explanation":"Superplasticisers greatly raise workability at the same water content, or cut water by 20–30% for higher strength, or allow less cement for the same strength.","marks":1,"source":{"kind":"past","set":15,"question":33,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q33 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-15-034","src":"PAST-15-034","text":"A laced column is …… than a battened column for the same load, unsupported length and end conditions.","options":[{"key":"a","text":"weaker"},{"key":"b","text":"stronger"},{"key":"c","text":"equally strong"},{"key":"d","text":"cannot be compared"}],"answer":"b","explanation":"Lacing forms a triangulated web that resists shear better than battens. Battened columns are more flexible, and IS 800 increases their effective length by 10%.","marks":1,"source":{"kind":"past","set":15,"question":34,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q34 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-15-068","src":"PAST-15-068","text":"A 200 mm thick brick masonry wall made of modular bricks is 5 m long between cross walls and has 3.8 m clear height between RCC slabs at the top and bottom. The slenderness ratio of the wall is","options":[{"key":"a","text":"15"},{"key":"b","text":"20"},{"key":"c","text":"19"},{"key":"d","text":"30"}],"answer":"c","explanation":"The key takes \\[\\dfrac{h}{t} = \\dfrac{3.8}{0.2} = 19\\] which is less than \\(\\dfrac{l}{t} = \\dfrac{5}{0.2} = 25\\). IS 1905 would reduce the effective height to \\(0.75H\\) for RCC slabs bearing on the wall, giving about 14.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-12-037-slenderness-of-a-wall.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Slenderness ratio of a wall between RCC slabs and cross walls'><img src='assets/civil-past-solutions/past-12-037-slenderness-of-a-wall.svg' width='720' height='420' loading='lazy' decoding='async' alt='The wall is 200 mm thick, 3.8 m high between RCC slabs and 5 m long between cross walls. The key takes the lesser of h/t = 3.8/0.2 = 19 and l/t = 5/0.2 = 25, giving a slenderness ratio of 19.'></a><figcaption>Slenderness ratio of a wall between RCC slabs and cross walls</figcaption></figure>","marks":2,"source":{"kind":"past","set":15,"question":68,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q68 · 2 marks"},"topic":"ACiE0506"},{"id":"PAST-15-070","src":"PAST-15-070","text":"In a roof truss, the value of snow load is taken as","options":[{"key":"a","text":"1.5 N/m<sup>2</sup>"},{"key":"b","text":"2.5 N/m<sup>2</sup>"},{"key":"c","text":"3.5 N/m<sup>2</sup>"},{"key":"d","text":"4.5 N/m<sup>2</sup>"}],"answer":"b","explanation":"IS 875 (Part 4) takes about 2.5 N per m<sup>2</sup> per mm depth of snow on flat surfaces, reduced for roof slopes.","marks":2,"source":{"kind":"past","set":15,"question":70,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q70 · 2 marks"},"topic":"ACiE0501"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-15-003","src":"PAST-15-003","text":"Which joint is mostly used at places where the pipe contracts (and expands) due to changes in atmospheric temperature?","options":[{"key":"a","text":"Expansion joint"},{"key":"b","text":"Socket and spigot joint"},{"key":"c","text":"Flange joint"},{"key":"d","text":"Screw joint"}],"answer":"a","explanation":"Expansion joints (sleeve type) are provided at intervals in exposed mains to absorb expansion and contraction of the pipe with temperature changes.","marks":1,"source":{"kind":"past","set":15,"question":3,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q3 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-15-035","src":"PAST-15-035","text":"EIA is defined as","options":[{"key":"a","text":"a process of identifying, predicting and evaluating the likely impacts of a proposed project or development to define mitigation actions to reduce negative impacts and to provide positive contributions to the natural environment and well-being"},{"key":"b","text":"a report written by government representatives on the planned development impacts on environment, socio-economic issues and culture"},{"key":"c","text":"project life-cycle assessment"},{"key":"d","text":"none of these"}],"answer":"a","explanation":"EIA is a systematic process that identifies, predicts and evaluates a proposal's environmental impacts before decisions are made and defines mitigation measures.","marks":1,"source":{"kind":"past","set":15,"question":35,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q35 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-15-036","src":"PAST-15-036","text":"Which method is accurate for forecasting population for sound and rapidly increasing cities?","options":[{"key":"a","text":"Arithmetical increase method"},{"key":"b","text":"Geometrical increase method"},{"key":"c","text":"Incremental increase method"},{"key":"d","text":"Graphical method"}],"answer":"b","explanation":"Young, rapidly growing cities grow at a roughly constant percentage rate, which the geometrical increase method models.","marks":1,"source":{"kind":"past","set":15,"question":36,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q36 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-15-037","src":"PAST-15-037","text":"Vacuum filters are used for","options":[{"key":"a","text":"filtration of sewage"},{"key":"b","text":"filtration of sludge"},{"key":"c","text":"dewatering of sludge"},{"key":"d","text":"both filtration of sewage and filtration of sludge"}],"answer":"c","explanation":"Rotary vacuum filters dewater digested or conditioned sludge into a cake with about 20–30% solids. They are not used to filter sewage.","marks":1,"source":{"kind":"past","set":15,"question":37,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q37 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-15-038","src":"PAST-15-038","text":"For a given discharge, the efficiency of a sedimentation tank can be increased by","options":[{"key":"a","text":"increasing depth of basin"},{"key":"b","text":"decreasing depth"},{"key":"c","text":"increasing area of basin"},{"key":"d","text":"decreasing area of basin"}],"answer":"c","explanation":"Ideal settling efficiency depends on the surface overflow rate Q/A. A larger plan area lowers it, so more (finer) particles settle; depth has no effect.","marks":1,"source":{"kind":"past","set":15,"question":38,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q38 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-15-050","src":"PAST-15-050","text":"A surface source of water is","options":[{"key":"a","text":"infiltration galleries"},{"key":"b","text":"wells"},{"key":"c","text":"streams"},{"key":"d","text":"springs"}],"answer":"c","explanation":"Streams, rivers, lakes and reservoirs are surface sources. Wells, springs and infiltration galleries draw on groundwater (subsurface) sources.","marks":1,"source":{"kind":"past","set":15,"question":50,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q50 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-15-071","src":"PAST-15-071","text":"What is the typical size and spacing of a coarse screen inclined at 45° to 60°, generally used for filtration?","options":[{"key":"a","text":"Bars of size 10-25 mm, with spacing of 20-100 mm"},{"key":"b","text":"Bars of size 5-15 mm, with spacing of 15-50 mm"},{"key":"c","text":"Bars of size 20-30 mm, with spacing of 25-75 mm"},{"key":"d","text":"Bars of size 30-50 mm, with spacing of 50-150 mm"}],"answer":"d","explanation":"Coarse screens (racks) are heavy steel bars set at 45°–60°, with wide clear openings of about 50–150 mm, to catch large floating objects. Fine screens use mesh of 6 mm or less.","marks":2,"source":{"kind":"past","set":15,"question":71,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q71 · 2 marks"},"topic":"ACiE0605"},{"id":"PAST-15-072","src":"PAST-15-072","text":"A group of 40 people have a water consumption of 105 lpcd. Find the peak factor for water supply demand for a flow of 350 ltr/hr.","options":[{"key":"a","text":"3"},{"key":"b","text":"1.33"},{"key":"c","text":"0.5"},{"key":"d","text":"2"}],"answer":"d","explanation":"The average flow is \\[\\dfrac{40 \\times 105}{24} = 175\\ \\text{L/h}\\] so the peak factor is \\[\\dfrac{350}{175} = 2\\]","marks":2,"source":{"kind":"past","set":15,"question":72,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q72 · 2 marks"},"topic":"ACiE0601"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-15-039","src":"PAST-15-039","text":"Which of the following factors decides the canal fall in the main channel?","options":[{"key":"a","text":"Commanded area"},{"key":"b","text":"Economy in earthwork balance"},{"key":"c","text":"Topography"},{"key":"d","text":"Regulating structure"}],"answer":"a","explanation":"The FSL must stay high enough to command the land and feed every off-take and outlet. Marking the FSL required at the commanded points fixes where falls can be placed, which is the key's reasoning.","marks":1,"source":{"kind":"past","set":15,"question":39,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q39 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-15-040","src":"PAST-15-040","text":"Which one of the following does not contribute to water logging?","options":[{"key":"a","text":"Inadequate drainage"},{"key":"b","text":"Seepage from unlined canals"},{"key":"c","text":"Frequent flooding"},{"key":"d","text":"Excessive tapping of ground water"}],"answer":"d","explanation":"Heavy pumping of groundwater lowers the water table, so it relieves rather than causes waterlogging. The other factors raise the water table.","marks":1,"source":{"kind":"past","set":15,"question":40,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q40 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-15-041","src":"PAST-15-041","text":"Which of the following is not considered a river-training structure?","options":[{"key":"a","text":"Spur"},{"key":"b","text":"Canal bund"},{"key":"c","text":"Launching apron"},{"key":"d","text":"Marginal guide bank"}],"answer":"b","explanation":"Spurs, launching aprons and marginal or guide banks control the river's course and banks. A canal bund is the embankment of an irrigation canal.","marks":1,"source":{"kind":"past","set":15,"question":41,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q41 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-15-042","src":"PAST-15-042","text":"Lacey's regime velocity is proportional to","options":[{"key":"a","text":"\\(R^{1/2}S^{3/4}\\)"},{"key":"b","text":"\\(Q^{3/4}S^{1/3}\\)"},{"key":"c","text":"\\(R^{3/4}S^{1/3}\\)"},{"key":"d","text":"\\(R^{2/3}S^{1/3}\\)"}],"answer":"d","explanation":"Lacey's regime flow equation is \\[V = 10.8R^{2{/}3}S^{1{/}3}\\]","marks":1,"source":{"kind":"past","set":15,"question":42,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q42 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-15-043","src":"PAST-15-043","text":"The irrigation interval is determined by","options":[{"key":"a","text":"field capacity to maximum crop water requirement"},{"key":"b","text":"irrigation capacity/irrigation efficiency"},{"key":"c","text":"evapotranspiration rate"},{"key":"d","text":"soil infiltration rate"}],"answer":"c","explanation":"The interval is the readily available soil moisture divided by the daily crop water use. For a given soil it is governed by the evapotranspiration rate, which is the key's answer.","marks":1,"source":{"kind":"past","set":15,"question":43,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q43 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-15-044","src":"PAST-15-044","text":"The most commonly used vertical lift gates in modern days are","options":[{"key":"a","text":"fixed wheel gates"},{"key":"b","text":"sliding gates"},{"key":"c","text":"free-roller gates"},{"key":"d","text":"slotted gates"}],"answer":"a","explanation":"Fixed-wheel gates, with wheels on axles fixed to the gate rolling on guide tracks, are the most common vertical-lift gates for spillways and intakes.","marks":1,"source":{"kind":"past","set":15,"question":44,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q44 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-15-045","src":"PAST-15-045","text":"A farm pond is used for","options":[{"key":"a","text":"erosion control"},{"key":"b","text":"flood control"},{"key":"c","text":"water storage"},{"key":"d","text":"runoff control"}],"answer":"c","explanation":"A farm pond stores harvested runoff for supplementary irrigation, livestock and domestic use.","marks":1,"source":{"kind":"past","set":15,"question":45,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q45 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-15-073","src":"PAST-15-073","text":"What should be the length of weir for a 50-year design flood of 4000 m<sup>3</sup>/s, if the bank to bank width of the river is 280 m?","options":[{"key":"a","text":"270 m"},{"key":"b","text":"280 m"},{"key":"c","text":"290 m"},{"key":"d","text":"300 m"}],"answer":"b","explanation":"Lacey's waterway \\[4.75\\sqrt{4000} \\approx 300\\ \\text{m}\\] exceeds the river width, so the weir is limited to the bank-to-bank width of 280 m.","marks":2,"source":{"kind":"past","set":15,"question":73,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q73 · 2 marks"},"topic":"ACiE0703"},{"id":"PAST-15-074","src":"PAST-15-074","text":"If \\(L = 400\\) m, find the upstream and downstream lengths of the guide bank.","options":[{"key":"a","text":"600 m and 100 m"},{"key":"b","text":"100 m and 600 m"},{"key":"c","text":"500 m and 100 m"},{"key":"d","text":"100 m and 500 m"}],"answer":"c","explanation":"Guide banks extend about 1.0-1.5L upstream and 0.2-0.4L downstream. The key takes \\[1.25L = 500\\ \\text{m}\\] \\[0.25L = 100\\ \\text{m}\\] upstream and downstream respectively.","marks":2,"source":{"kind":"past","set":15,"question":74,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q74 · 2 marks"},"topic":"ACiE0704"}]},{"name":"Hydropower","questions":[{"id":"PAST-15-046","src":"PAST-15-046","text":"Which of the following plants uses a reversible turbine that can work at relatively high efficiencies and helps in reducing the cost of such a plant?","options":[{"key":"a","text":"Run-off river plant"},{"key":"b","text":"Storage plant"},{"key":"c","text":"Pumped storage plant"},{"key":"d","text":"Tidal plant"}],"answer":"c","explanation":"Pumped-storage plants use reversible pump-turbines: one machine pumps water up off-peak and generates at peak, which saves separate pumps and turbines.","marks":1,"source":{"kind":"past","set":15,"question":46,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q46 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-15-048","src":"PAST-15-048","text":"In the context of Nepal, which of the following power plants is most reliable/suitable?","options":[{"key":"a","text":"Diesel plant"},{"key":"b","text":"Hydro and diesel plant"},{"key":"c","text":"Hydro plant"},{"key":"d","text":"Wind plant"}],"answer":"c","explanation":"Nepal has steep rivers and huge hydro potential (about 83,000 MW theoretical) but no fossil fuel, so hydropower is the most suitable and economical source.","marks":1,"source":{"kind":"past","set":15,"question":48,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q48 · 1 mark"},"topic":"ACiE0801"},{"id":"PAST-15-049","src":"PAST-15-049","text":"What is the function of a surge tank?","options":[{"key":"a","text":"It causes water hammer"},{"key":"b","text":"Produces surge in the pipeline"},{"key":"c","text":"Relieves water hammer"},{"key":"d","text":"Supplies water at constant pressure"}],"answer":"c","explanation":"The surge tank relieves water-hammer pressures by absorbing sudden changes of flow in the conduit.","marks":1,"source":{"kind":"past","set":15,"question":49,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q49 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-15-075","src":"PAST-15-075","text":"A 4 m diameter tunnel has been constructed through an earth dam with a bell mouth entry. The water levels on the U/s and D/s sides of the dam are at RL 226 m and 210 m respectively. What will be the discharge through this outlet?","options":[{"key":"a","text":"64 m<sup>3</sup>/s"},{"key":"b","text":"104 m<sup>3</sup>/s"},{"key":"c","text":"165 m<sup>3</sup>/s"},{"key":"d","text":"178.12 m<sup>3</sup>/s"}],"answer":"d","explanation":"The head is \\(H = 226 - 210 = 16\\) m and the area is \\[A = \\dfrac{\\pi \\times 4^2}{4} = 12.57\\ \\text{m}^2\\] With \\(C_d \\approx 0.8\\), \\[\\begin{aligned} Q &amp;= C_dA\\sqrt{2gH} \\\\ &amp;= 0.8 \\times 12.57 \\times 17.72 \\\\ &amp;\\approx 178\\ \\text{m}^3\\text{/s} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":15,"question":75,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q75 · 2 marks"},"topic":"ACiE0803"},{"id":"PAST-15-076","src":"PAST-15-076","text":"Which of the following is correct? (i) A diesel engine works as base load. (ii) Storage hydropower is used for peak time.","options":[{"key":"a","text":"i"},{"key":"b","text":"ii"},{"key":"c","text":"Both"},{"key":"d","text":"None"}],"answer":"b","explanation":"Diesel sets are costly to run and are used for peak or standby duty, not base load. Storage hydro can start quickly and store water, so it serves the peak. Only statement (ii) is correct.","marks":2,"source":{"kind":"past","set":15,"question":76,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q76 · 2 marks"},"topic":"ACiE0802"}]},{"name":"Transportation","questions":[{"id":"PAST-15-009","src":"PAST-15-009","text":"The gradual decrease in volume of soil on application of load due to expulsion of air is called","options":[{"key":"a","text":"Collapse"},{"key":"b","text":"Consolidation"},{"key":"c","text":"Shrinkage"},{"key":"d","text":"Compaction"}],"answer":"d","explanation":"Compaction densifies soil by expelling air under mechanical loading. Expelling pore water under sustained load is consolidation.","marks":1,"source":{"kind":"past","set":15,"question":9,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q9 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-15-011","src":"PAST-15-011","text":"Which type of roller should be selected for effective compaction of coarse grained soil?","options":[{"key":"a","text":"Sheep foot roller"},{"key":"b","text":"Smooth wheeled roller"},{"key":"c","text":"Vibratory roller"},{"key":"d","text":"Pneumatic tyre roller"}],"answer":"c","explanation":"Vibration rearranges cohesionless grains into a dense packing, so vibratory rollers are most effective on sands and gravels.","marks":1,"source":{"kind":"past","set":15,"question":11,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q11 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-15-013","src":"PAST-15-013","text":"Which of the following factors does not affect soil compaction?","options":[{"key":"a","text":"Type of compaction"},{"key":"b","text":"Soil type"},{"key":"c","text":"Number of compaction blows"},{"key":"d","text":"Bed stability"}],"answer":"d","explanation":"Compaction depends on the soil type, its water content and the compactive effort (method, number of blows or passes). 'Bed stability' is not a compaction factor.","marks":1,"source":{"kind":"past","set":15,"question":13,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q13 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-15-051","src":"PAST-15-051","text":"The most reliable mode of transportation is","options":[{"key":"a","text":"water transport"},{"key":"b","text":"road transport"},{"key":"c","text":"air transport"},{"key":"d","text":"railway transport"}],"answer":"c","explanation":"The key takes air transport as the most reliable mode: fast, on fixed schedules and unaffected by terrain or surface obstructions.","marks":1,"source":{"kind":"past","set":15,"question":51,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q51 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-15-052","src":"PAST-15-052","text":"The traffic sign used for a school is a","options":[{"key":"a","text":"cautionary sign"},{"key":"b","text":"informatory sign"},{"key":"c","text":"mandatory sign"},{"key":"d","text":"both informatory and cautionary"}],"answer":"a","explanation":"The 'school ahead' sign is a cautionary (warning) sign, a triangular sign that alerts drivers to children near the road. Mandatory signs such as stop or speed limits carry legal force.","marks":1,"source":{"kind":"past","set":15,"question":52,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q52 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-15-053","src":"PAST-15-053","text":"Which of the following is commonly used as an organic binding material in road construction?","options":[{"key":"a","text":"Stone dust"},{"key":"b","text":"Bitumen"},{"key":"c","text":"Limestone"},{"key":"d","text":"Sand"}],"answer":"b","explanation":"Bitumen, a hydrocarbon binder, is the common organic binder in flexible pavements. The other options are mineral aggregates or fillers.","marks":1,"source":{"kind":"past","set":15,"question":53,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q53 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-15-054","src":"PAST-15-054","text":"Which one of the following is not a fixed facility?","options":[{"key":"a","text":"Railway"},{"key":"b","text":"Roadway"},{"key":"c","text":"Airway"},{"key":"d","text":"Railway locomotive"}],"answer":"d","explanation":"Railways, roads and airways (with terminals) are fixed facilities (infrastructure). A locomotive is a vehicle, i.e. a mobile unit.","marks":1,"source":{"kind":"past","set":15,"question":54,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q54 · 1 mark"},"topic":"ACiE0901"},{"id":"PAST-15-055","src":"PAST-15-055","text":"The distance travelled by a moving vehicle during the perception and brake reaction time is known as","options":[{"key":"a","text":"sight distance"},{"key":"b","text":"stopping distance"},{"key":"c","text":"lag distance"},{"key":"d","text":"passing distance"}],"answer":"c","explanation":"The lag distance \\(vt\\) is travelled during the perception-reaction time before the brakes act. SSD is the lag distance plus the braking distance.","marks":1,"source":{"kind":"past","set":15,"question":55,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q55 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-15-077","src":"PAST-15-077","text":"Benkelman beam deflection studies were carried out on a highway pavement at a temperature of 40°C. The rebound deflection was found to be 1.41 mm. What would be the corrected rebound deflection?","options":[{"key":"a","text":"1.33 mm"},{"key":"b","text":"1.35 mm"},{"key":"c","text":"1.40 mm"},{"key":"d","text":"1.36 mm"}],"answer":"d","explanation":"The deflection is corrected to the standard \\(35^\\circ\\text{C}\\) at 0.01 mm per \\(^\\circ\\text{C}\\): \\[\\begin{aligned} &amp;1.41 - 0.01 \\times (40 - 35) \\\\ &amp;= 1.36\\ \\text{mm} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":15,"question":77,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q77 · 2 marks"},"topic":"ACiE0905"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-15-056","src":"PAST-15-056","text":"The minimum qualification of the registrar of NEC is","options":[{"key":"a","text":"Bachelor's degree + 10 years' experience"},{"key":"b","text":"Bachelor's degree + 15 years' experience"},{"key":"c","text":"Bachelor's degree + 20 years' experience"},{"key":"d","text":"Bachelor's degree + 7 years' experience"}],"answer":"a","explanation":"Per the key, the NEC Registrar must hold at least a bachelor's degree in engineering with 10 years' experience. The chairperson needs 15 years.","marks":1,"source":{"kind":"past","set":15,"question":56,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q56 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-15-057","src":"PAST-15-057","text":"Which of the following involves continuous betterment in planning and detailing with time?","options":[{"key":"a","text":"Project enhancement"},{"key":"b","text":"Progressive rehabilitation"},{"key":"c","text":"Progressive elaboration"},{"key":"d","text":"Continuous improvement"}],"answer":"c","explanation":"Progressive elaboration (PMBOK) is the continual refinement of project plans and details as more information becomes available over the project's life.","marks":1,"source":{"kind":"past","set":15,"question":57,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q57 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-15-058","src":"PAST-15-058","text":"According to the Labour Act, the maximum working hours in a day is","options":[{"key":"a","text":"5 hours"},{"key":"b","text":"7 hours"},{"key":"c","text":"8 hours"},{"key":"d","text":"12 hours"}],"answer":"c","explanation":"Nepal's Labour Act 2074 limits normal working time to 8 hours a day and 48 hours a week. Overtime is paid extra and is capped.","marks":1,"source":{"kind":"past","set":15,"question":58,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q58 · 1 mark"},"topic":"AALL1005"},{"id":"PAST-15-059","src":"PAST-15-059","text":"The assessment done by the implementing agency to check the eligibility of a firm to carry out the contract is","options":[{"key":"a","text":"pre-qualification"},{"key":"b","text":"tender assessment"},{"key":"c","text":"post-qualification"},{"key":"d","text":"contract assessment"}],"answer":"a","explanation":"Pre-qualification checks a firm's experience, capacity and resources before it is invited to bid.","marks":1,"source":{"kind":"past","set":15,"question":59,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q59 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-15-060","src":"PAST-15-060","text":"Quality and workmanship in construction projects are defined in","options":[{"key":"a","text":"construction drawings"},{"key":"b","text":"estimate"},{"key":"c","text":"specifications"},{"key":"d","text":"bill of quantities (BOQ)"}],"answer":"c","explanation":"Specifications describe the materials, workmanship, methods and tests. Drawings give dimensions and the BOQ gives quantities.","marks":1,"source":{"kind":"past","set":15,"question":60,"marks":1,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q60 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-15-078","src":"PAST-15-078","text":"What is the top view of a right regular hexagonal pyramid resting on its base with its axis vertical?","options":[{"key":"a","text":"A triangle showing the slant edges (its front view)"},{"key":"b","text":"A plain triangle"},{"key":"c","text":"A pentagon with its slant edges"},{"key":"d","text":"A regular hexagon with lines joining its centre to every corner"}],"answer":"d","explanation":"Looking down the axis, the base appears as a true hexagon and the slant edges run from the apex, seen at the centre, to each corner. (The paper gives the options as sketches; the question is reworded.)","marks":2,"source":{"kind":"past","set":15,"question":78,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q78 · 2 marks"},"topic":"AALL1001"},{"id":"PAST-15-079","src":"PAST-15-079","text":"As per the NEC Act (amended 2079), section 30(c), the punishment for violation of rules is","options":[{"key":"a","text":"2000"},{"key":"b","text":"3000"},{"key":"c","text":"20000"},{"key":"d","text":"25000"}],"answer":"d","explanation":"Per the source key, the amended NEC Act sets a fine of up to Rs 25,000 under section 30(c). This is a statute-based fact.","marks":2,"source":{"kind":"past","set":15,"question":79,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q79 · 2 marks"},"topic":"AALL1006"},{"id":"PAST-15-080","src":"PAST-15-080","text":"While representing a diameter in dimensioning, it is represented as","options":[{"key":"a","text":"D"},{"key":"b","text":"Ø"},{"key":"c","text":"Dia"},{"key":"d","text":"d"}],"answer":"b","explanation":"Diameters are dimensioned with the symbol Ø placed before the value (for example Ø20). Radii use R.","marks":2,"source":{"kind":"past","set":15,"question":80,"marks":2,"date":"2080 Chaitra 28","shift":"2nd shift","reference":"Past Paper Set 15, Q80 · 2 marks"},"topic":"AALL1001"}]}]};
